window.__saqPaperQuestions("2021-2-northern-sydney",[{"number":1,"title":"","stemText":"A 25-year-old female has taken an aspirin overdose","parts":[{"id":"a","label":"Part A","prompt":"Discuss the role of activated charcoal in the treatment of aspirin overdose (3 marks)"},{"id":"b","label":"Part B","prompt":"There are two therapeutic reasons to treat severe salicylate toxicity with sodium bicarbonate. Write a brief explanation (4 marks)"},{"id":"c","label":"Part C","prompt":"Detail how you will administer sodium bicarbonate to this patient (3 marks)"},{"id":"d","label":"Part D","prompt":"What other pharmacological adjuncts should be considered in this setting and why? (4 marks)"},{"id":"e","label":"Part E","prompt":"If the patient became drowsy with a compromised airway, what modifications would you make to routine intubation/ventilation? (2 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Generally rapid absorption but depends on formulation (e.g. enteric coating) and in OD can get</div><div class=\"answer-line\">delayed absorption due to bezoar formation, pylorospasm and long delays to peak levels. If not</div><div class=\"answer-line\">contra-indicated (decreased LOC etc) activated charcoal is given up to 6 hours post-ingestion in the</div><div class=\"answer-line\">awake patient and anytime in the intubated patient. Repeat dose at 4 hours is given if salicylate</div><div class=\"answer-line\">levels continue to rise</div><div class=\"answer-line\"><strong>ii.</strong><strong> </strong></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Serum alkalinisation: Aspirin is a weak acid. At physiological pH it is mostly ionised. As pH falls it</div><div class=\"answer-line\">shifts to non-ionised, less polar state which crosses the CNS BBB better, worsening toxicity. Critical</div><div class=\"answer-line\">to alkalinise (with Na Bic) and to avoid iatrogenic respiratory acidosis to prevent/manage CNS</div><div class=\"answer-line\">toxicity</div><div class=\"answer-line\">Urinary alkalinisation: Alkalinisation of the urine pushes aspirin into more polar state – less</div><div class=\"answer-line\">reabsorption at tubules  “ion trapping” and enhanced elimination</div><div class=\"answer-line\"><strong>iii.</strong><strong> </strong></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Sodium bicarbonate 8.4% 1 mL/kg up to 100 mL (1 mmol/kg up to 100 mmol)</div><div class=\"answer-line\">intravenously, as an initial dose</div><div class=\"answer-line\">FOLLOWED BY</div><div class=\"answer-line\">Nth Syd SAQ paper 2021.2</div><div class=\"answer-line\">sodium bicarbonate 25 mmol/hour by intravenous infusion. To administer 25 mmol/hour of</div><div class=\"answer-line\">sodium bicarbonate, add 150 mL of sodium bicarbonate 8.4% to 850 mL glucose 5% (ie remove</div><div class=\"answer-line\">150 mL from a 1000 mL bag of glucose 5%) and infuse at a rate of 166 mL/hour</div><div class=\"answer-line\"><strong>iv.</strong><strong> </strong></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\"><strong>Potassium</strong>. Hypokalaemia impedes the ability of the kidney to alkalinise the urine. The kidney retains</div><div class=\"answer-line\">potassium by secreting hydrogen ions (exchanging H for K). Serum potassium needs to be</div><div class=\"answer-line\">maintained around 3.5-4 mmol/L –  give 10-20 mmol / hour IV every 2-4 hours as required.</div><div class=\"answer-line\"><strong>Glucose. </strong>Aspirin intoxication may decrease cerebral glucose concentrations despite a normal serum</div><div class=\"answer-line\">glucose. Thus, supplemental glucose should be given to patients with an altered mental status</div><div class=\"answer-line\">regardless of the serum glucose concentration</div><div class=\"answer-line\">(benzodiazepines if seizures - )</div><div class=\"answer-line\"><strong>v.</strong><strong> </strong></div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Intubation is hazardous. Patients typically have a very high minute volume (MV) due to increased</td></tr><tr><td colspan=\"2\">central respiratory drive. Peri-intubation apnoea and/or decrease in MV can cause a concomitant</td></tr><tr><td colspan=\"2\">iatrogenic respiratory acidosis, increased CNS salicylate concentrations and death.</td></tr><tr><td>•</td><td>Most experienced operator etc</td></tr><tr><td>•</td><td>Bag through the apnoeic period</td></tr><tr><td>•</td><td>Try to match pre-induction MV (difficult)</td></tr><tr><td colspan=\"2\">Nth Syd SAQ paper 2021.2</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":2,"title":"","stemText":"A 45-year-old female with a background history of hypertension and cigarette smoking presents following a sudden syncopal episode while sitting at a café with a friend. She has now fully recovered and has normal vital signs. She says that she had some mild reflux type discomfort during the lunch and reports a family history of sudden death.","parts":[{"id":"a","label":"Part A","prompt":"Complete the table comparing the ECG findings and pathogenesis of Wellen’s syndrome\nand Type 1 Brugada syndrome (4 marks)"},{"id":"b","label":"Part B","prompt":"List 4 other causes of T wave inversion in the anterior leads (4 marks)"},{"id":"c","label":"Part C","prompt":"You consider the possibility of inherited Hypertrophic Cardiomyopathy (HCM) in this\npatient. List and describe 4 of the classical examination findings of HCM (4 marks)"},{"id":"d","label":"Part D","prompt":"What ECG findings would you expect to see in HCM? (3 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>Wellen’s</td><td>Critical stenosis LAD</td><td></td></tr><tr><td colspan=\"3\"><strong>V2-3, </strong>isoelectric or minimally elevated</td></tr><tr><td colspan=\"3\">(&lt;1mm) ST segment, no precordial Qs,</td></tr><tr><td colspan=\"3\">preserved R progression<strong> </strong></td></tr><tr><td>Brugada</td><td>Coved ST elevation &gt; 2mm in more</td><td>Channelopathy/Na channel</td></tr><tr><td>than one of V1-3 followed by a</td><td>mutation. Spontaneous or inherited.</td><td></td></tr><tr><td colspan=\"3\">negative T wave</td></tr><tr><td colspan=\"3\"><strong>ii.</strong><strong> </strong></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Arrythmogenic RV Dysplasia</div><div class=\"answer-line\">Myocardial ischaemia</div><div class=\"answer-line\">Myo/pericarditis</div><div class=\"answer-line\">PE</div><div class=\"answer-line\">SAH</div><div class=\"answer-line\"><strong>iii.</strong><strong> </strong></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Apex beat – double or triple</div><div class=\"answer-line\">Auscultation – late systolic ejection murmur (left sternal edge), pansystolic murmur from MR (apex),</div><div class=\"answer-line\">4th heart sound</div><div class=\"answer-line\">Dynamic manoeuvres – murmur louder with Valsalva – softer with squatting (increases preload) &amp;</div><div class=\"answer-line\">isometric exercise e.g. hand grip (increases afterload)</div><div class=\"answer-line\">Nth Syd SAQ paper 2021.2</div><div class=\"answer-line\"><strong>iv.</strong><strong> </strong></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Left ventricular hypertrophy with increased precordial voltages and non-specific ST &amp; T</div><div class=\"answer-line\">abnormalities</div><div class=\"answer-line\">Deep, narrow (“dagger-lioke”) Q waves in lateral +/- inferior leads</div><div class=\"answer-line\">Left atrial enlargement - P mitrale</div><div class=\"answer-line\">Signs of WPW – short PR, delta wave</div><div class=\"answer-line\">Pre-cordial T inversion</div><div class=\"answer-line\">Nth Syd SAQ paper 2021.2</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":3,"title":"","stemText":"A 2 year old normally well boy presents to your ED with a 5 day history of fever, maculopapular rash\n• n thighs and arms, poor oral intake and lethargy.","parts":[{"id":"a","label":"Part A","prompt":"You are concerned about Kawasaki Disease (KD). Describe the diagnostic criteria for Kawasaki’s (4 marks)"},{"id":"b","label":"Part B","prompt":"List 3 other potential differential diagnoses (3 marks)"},{"id":"c","label":"Part C","prompt":"What is PIMS TS? (2 marks)"},{"id":"d","label":"Part D","prompt":"What is the treatment for KD and PIMS TS? (3 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Diagnostic criteria for Kawasaki disease (up to date)</div><div class=\"answer-line\">Fever lasting at least 5 days without any other explanation with at least 4 of the 5 following criteria</div><div class=\"answer-line\">1. Bilateral bulbar conjunctival injection</div><div class=\"answer-line\">2. Oral mucous membrane changes , including injected or fissured lips, injected pharynx, or</div><div class=\"answer-line\">strawberry tongue</div><div class=\"answer-line\">3. Peripheral extremity changes, including erythema of palms or soles, edema of hands or feet</div><div class=\"answer-line\">(acute phase), and periungual desquamation (convalescent phase)</div><div class=\"answer-line\">4. Polymorphous rash</div><div class=\"answer-line\">5. Cervical lymphadenopathy (at least 1 lymph node &gt;1.5cm diameter)</div><div class=\"answer-line\">If ≥4 of the above criteria are present, a diagnosis of KD can be made on day 4 of illness</div><div class=\"answer-line\"><strong>ii.</strong><strong> </strong></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">2. Adenovirus</div><div class=\"answer-line\">3. Enterovirus</div><div class=\"answer-line\">4. PIMS TS</div><div class=\"answer-line\">( PRETTY MUCH ANY VIRAL EXANTHEM!)</div><div class=\"answer-line\"><strong>Differential Diagnosis</strong></div><div class=\"answer-line\"><strong>Viral </strong>Measles, Adenovirus, Enterovirus, Epstein-Barr virus</div><div class=\"answer-line\"><strong>Bacterial </strong>Scarlet fever, Acute rheumatic fever, Rocky mountain spotted fever, Leptospirosis, Cervical</div><div class=\"answer-line\">lymphadenitis</div><div class=\"answer-line\"><strong>Toxin-mediated</strong> Staphylococcal scalded skin syndrome, Toxic shock syndrome</div><div class=\"answer-line\"><strong>Hypersensitivity reactions </strong>Drug hypersensitivity reaction, Steven-Johnson syndrome</div><div class=\"answer-line\"><strong>Rheumatic disease </strong>Juvenile idiopathic arthritis, Polyarteritis nodosa, Reactive arthritis</div><div class=\"answer-line\"><strong>Toxicity </strong>Acrodynia (mercury poisoning)</div><div class=\"answer-line\"><strong>Other</strong> Multisystem inflammatory syndrome in children</div><div class=\"answer-line\">Nth Syd SAQ paper 2021.2</div><div class=\"answer-line\"><strong>iii.</strong><strong> </strong></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Paediatric Inflammatory multisystem Syndrome Temporally associated with SARS-COV-2</td></tr><tr><td colspan=\"2\">(PIMS-TS) Or US CDC Multisystem Inflammatory Syndrome in Children associated with</td></tr><tr><td colspan=\"2\">COVID 19 (MIS-C)</td></tr><tr><td>•</td><td>Individual aged &lt; 21 years presenting with fever, lab evidence of inflammation and evidence</td></tr><tr><td colspan=\"2\">of clinically severe illness requiring hospitalization with multisystem  (&gt;2) organ involvement</td></tr><tr><td colspan=\"2\">(cardiac, renal, respiratory, haemotologic, GI, deratologic or neurological); AND</td></tr><tr><td>•</td><td>No alternate plausible diagnoses AND</td></tr><tr><td>•</td><td>Positive for current or recent SARS COV-2 infection by RT PCR, serology or antigen test; or</td></tr><tr><td colspan=\"2\">COVID 19 exposure within the 4 weeks prior to the onset of symptoms</td></tr><tr><td>•</td><td>Fever &gt; 38 for &gt; 24 hours</td></tr><tr><td>•</td><td>Raised CRP, ESR, fibrinogen, procalcitonin, D dimer, ferritin, LDH or IL-6, elevated</td></tr><tr><td colspan=\"2\">neutrophils, reduced lymphocytes, and low albumin</td></tr><tr><td colspan=\"2\"><strong>iv.</strong><strong> </strong></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">IVIG 2g/kg  - First line – gold standard</div><div class=\"answer-line\">Aspirin</div><div class=\"answer-line\">IVIG most effective if administered within 10days of onset of fever</div><div class=\"answer-line\">Reduced incidence of coronaray artery aneurysm from 20-25% to 3-5%</div><div class=\"answer-line\">Risk factors: delay initial IVIG</div><div class=\"answer-line\">increased ESR</div><div class=\"answer-line\">decreased Haemoglobin &amp; Thrombocytopenia</div><div class=\"answer-line\">oral mucosa alterations</div><div class=\"answer-line\">cervical lymphadenopathy</div><div class=\"answer-line\">extremity swelling</div><div class=\"answer-line\">polymorphous rash</div><div class=\"answer-line\">Children with risk factors should receive 2nd dose of IVIG</div><div class=\"answer-line\">Corticosteroids – considered in patients that are high risk for coronary aneurysm</div><div class=\"answer-line\">Treatment options under research – TNF inhibitor, IL-1 Inhibitor, Calcineurin Inhibitor</div><div class=\"answer-line\">Nth Syd SAQ paper 2021.2</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":4,"title":"","stemText":"With regard to skin and soft tissue infections","parts":[{"id":"a","label":"Part A","prompt":"List 5 non-infectious conditions that masquerade as unilateral leg cellulitis and indicate the symptoms/signs and/or tests that help to differentiate the condition from cellulitis (10 marks) Cellulitis mimic Differentiating symptoms/signs/investigations"},{"id":"b","label":"Part B","prompt":"List 2 choices of oral antibiotic suitable for empiric treatment of non-purulent cellulitis without systemic features (2 marks)"},{"id":"c","label":"Part C","prompt":"List 2 choices of oral antibiotic suitable for empiric treatment of purulent cellulitis without systemic features (2 marks)"},{"id":"d","label":"Part D","prompt":"Briefly explain the pharmacodynamic advantage conferred by combining a beta-lactam antibiotic with: (a) Probenecid (2 marks) (b) Clavulanic acid (2 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Contact dermatitis - contact dermatitis lesions are pruritic. Clinical features include erythema,</td></tr><tr><td colspan=\"2\">oedema, vesicles, bullae, and oozing. The reaction is generally limited to the site of contact and is</td></tr><tr><td colspan=\"2\">associated with burning, stinging, or pain. Usually well-demarcated. Frequently a history of contact</td></tr><tr><td colspan=\"2\">with causative agent</td></tr><tr><td colspan=\"2\">Acute gout - severe pain, warmth, erythema, and swelling overlying a single joint. The diagnosis can</td></tr><tr><td colspan=\"2\">be established by synovial fluid analysis, which should demonstrate the characteristic urate crystals</td></tr><tr><td colspan=\"2\">of gout or the calcium pyrophosphate crystals of pseudogout. Additional clues suggestive of gout</td></tr><tr><td colspan=\"2\">include involvement of the first metatarsophalangeal joint, prior self-limited attacks of arthritis, and</td></tr><tr><td colspan=\"2\">presence of tophi.</td></tr><tr><td colspan=\"2\">Insect bite - inflammatory reaction at the site of the punctured skin, which appears within minutes</td></tr><tr><td colspan=\"2\">and consists of pruritic local erythema and oedema. May/may not give history of bite or outdoor</td></tr><tr><td colspan=\"2\">activities. In some cases, a local reaction is followed by a delayed skin reaction consisting of local</td></tr><tr><td colspan=\"2\">swelling, itching, and erythema.</td></tr><tr><td colspan=\"2\">Nth Syd SAQ paper 2021.2</td></tr><tr><td colspan=\"2\">Stasis dermatitis – Stasis dermatitis is an inflammatory dermatosis of the lower extremities that</td></tr><tr><td colspan=\"2\">occurs in patients with chronic venous insufficiency. It is usually bilateral but can be unilateral in the</td></tr><tr><td colspan=\"2\">setting of anatomic asymmetry. The diagnosis is usually established clinically</td></tr><tr><td colspan=\"2\">Drug reaction - presents with an erythematous maculopapular rash that involves the trunk and</td></tr><tr><td colspan=\"2\">proximal extremities. It may be accompanied by pruritus, low-grade fever, and mild eosinophilia.</td></tr><tr><td colspan=\"2\">The diagnosis is suspected in a patient receiving drug treatment who presents with a rash of recent</td></tr><tr><td colspan=\"2\">onset. The clinical suspicion can be substantiated by histopathologic examination of a skin biopsy</td></tr><tr><td colspan=\"2\">Superficial thrombophlebitis -  ender, palpable cord along affected vein often present. History of</td></tr><tr><td colspan=\"2\">cannulation.</td></tr><tr><td colspan=\"2\">DVT – tenderness +/- Homan’s, diffuse swelling history of prior DVT, prolonged immobility, or</td></tr><tr><td colspan=\"2\">hypercoagulable state.</td></tr><tr><td colspan=\"2\">Vasculitis - macular and papular lesions are characteristically nonblanchable due to the presence of</td></tr><tr><td colspan=\"2\">extravasated erythrocytes in the dermis, which occurs as a result of damaged vessel walls. The</td></tr><tr><td colspan=\"2\">diagnosis is established by skin biopsy</td></tr><tr><td><strong>ii.</strong><strong> </strong></td><td><strong>List 2 choices of oral antibiotic suitable for empiric treatment of </strong><em><strong>non-purulent</strong></em><strong> cellulitis </strong></td></tr><tr><td colspan=\"2\"><strong>without systemic features (2 marks) </strong></td></tr><tr><td>•</td><td>Phenoxymethylpenicillin 500mg 6-hourly for 5 days</td></tr><tr><td>•</td><td>Cephalexin 500mg 6-hourly</td></tr><tr><td>•</td><td>Clindamycin 450mg 8-hourly</td></tr><tr><td colspan=\"2\"><strong>iii.</strong><strong> </strong></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Flucloxacillin 500-1000mg 6-hourly (or dicloxacillin)</td></tr><tr><td>•</td><td>Cephalexin 500mg 6-hourly</td></tr><tr><td>•</td><td>Clindamycin 450mg 8-hourly</td></tr><tr><td>•</td><td>Bactrim 160/800 12-hourly</td></tr><tr><td><strong>iv.</strong><strong> </strong></td><td><strong>Briefly explain the pharmacodynamic advantage conferred by combining a beta-lactam </strong></td></tr><tr><td colspan=\"2\"><strong>antibiotic with: </strong></td></tr><tr><td colspan=\"2\"><strong>(a)</strong><strong> </strong><strong>Probenecid (2 marks) </strong></td></tr><tr><td colspan=\"2\">Nth Syd SAQ paper 2021.2</td></tr><tr><td>•</td><td>Decreases renal excretion of drugs that undergo active tubular secretion – especially</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Inhibitor of bacterial B lactamases and protect hydrolysable penicillins from</div><div class=\"answer-line\">inactivation. Weak antibiotic action in their own right. Do not alter the antibacterial</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Nth Syd SAQ paper 2021.2</td></tr><tr><td colspan=\"2\">Stasis dermatitis – Stasis dermatitis is an inflammatory dermatosis of the lower extremities that</td></tr><tr><td colspan=\"2\">occurs in patients with chronic venous insufficiency. It is usually bilateral but can be unilateral in the</td></tr><tr><td colspan=\"2\">setting of anatomic asymmetry. The diagnosis is usually established clinically</td></tr><tr><td colspan=\"2\">Drug reaction - presents with an erythematous maculopapular rash that involves the trunk and</td></tr><tr><td colspan=\"2\">proximal extremities. It may be accompanied by pruritus, low-grade fever, and mild eosinophilia.</td></tr><tr><td colspan=\"2\">The diagnosis is suspected in a patient receiving drug treatment who presents with a rash of recent</td></tr><tr><td colspan=\"2\">onset. The clinical suspicion can be substantiated by histopathologic examination of a skin biopsy</td></tr><tr><td colspan=\"2\">Superficial thrombophlebitis -  ender, palpable cord along affected vein often present. History of</td></tr><tr><td colspan=\"2\">cannulation.</td></tr><tr><td colspan=\"2\">DVT – tenderness +/- Homan’s, diffuse swelling history of prior DVT, prolonged immobility, or</td></tr><tr><td colspan=\"2\">hypercoagulable state.</td></tr><tr><td colspan=\"2\">Vasculitis - macular and papular lesions are characteristically nonblanchable due to the presence of</td></tr><tr><td colspan=\"2\">extravasated erythrocytes in the dermis, which occurs as a result of damaged vessel walls. The</td></tr><tr><td colspan=\"2\">diagnosis is established by skin biopsy</td></tr><tr><td colspan=\"2\"><strong>ii.</strong><strong> </strong></td></tr><tr><td>•</td><td>Phenoxymethylpenicillin 500mg 6-hourly for 5 days</td></tr><tr><td>•</td><td>Cephalexin 500mg 6-hourly</td></tr><tr><td>•</td><td>Clindamycin 450mg 8-hourly</td></tr><tr><td colspan=\"2\"><strong>iii.</strong><strong> </strong></td></tr><tr><td>•</td><td>Flucloxacillin 500-1000mg 6-hourly (or dicloxacillin)</td></tr><tr><td>•</td><td>Cephalexin 500mg 6-hourly</td></tr><tr><td>•</td><td>Clindamycin 450mg 8-hourly</td></tr><tr><td>•</td><td>Bactrim 160/800 12-hourly</td></tr><tr><td colspan=\"2\"><strong>iv.</strong><strong> </strong></td></tr><tr><td colspan=\"2\">Nth Syd SAQ paper 2021.2</td></tr><tr><td>•</td><td>Decreases renal excretion of drugs that undergo active tubular secretion – especially</td></tr><tr><td colspan=\"2\">weak acids &amp; including B-lactam antibiotics. Pharmacokinetic principles  longer</td></tr><tr><td colspan=\"2\">period where concentration of drug stays above MIC</td></tr><tr><td colspan=\"2\"><strong>(b)</strong><strong> </strong><strong>Clavulanic acid (2 marks) </strong></td></tr><tr><td>•</td><td>Inhibitor of bacterial B lactamases and protect hydrolysable penicillins from</td></tr><tr><td colspan=\"2\">inactivation. Weak antibiotic action in their own right. Do not alter the antibacterial</td></tr><tr><td colspan=\"2\">spectrum of the parent antibiotic</td></tr><tr><td colspan=\"2\">Nth Syd SAQ paper 2021.2</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":5,"title":"","stemText":"You are contacted on the bat phone about a 45 year old man who is cardiac arrest. The ETA is 10 minutes.","parts":[{"id":"a","label":"Part A","prompt":"List 8 factors that are good pre-hospital prognostic indicators in an out of hospital cardiac arrest (4 Marks) On arrival the patient has been in arrest for 30 minutes and remains in VF. He is on a mechanical CPR device and his airway has been secured with an ET tube. He has received 5 DC shocks. He has been\ngiven 3 x 1mg Adrenaline and 450 mg of Amiodarone."},{"id":"b","label":"Part B","prompt":"What other drug would you consider giving next for his arrythmia? (2 Marks) Following administration and with CPR on going you notice the end tidal CO2 goes from 15 to 45 mmHg."},{"id":"c","label":"Part C","prompt":"How would you explain this change physiologically and how would it alter your management? (2 marks)"},{"id":"d","label":"Part D","prompt":"At this stage you note the patient starts to bite on the ETT tube. How would you manage the ongoing resuscitation of this patient? (4 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Age &lt; 65 (young)</div><div class=\"answer-line\">Witnessed arrest</div><div class=\"answer-line\">Immediate Bystander CPR</div><div class=\"answer-line\">Initially Shockable rhythm</div><div class=\"answer-line\">No asystole</div><div class=\"answer-line\">Lack of comorbidities</div><div class=\"answer-line\">Signs of life – tearing, moving arms</div><div class=\"answer-line\">Short duration of CPR</div><div class=\"answer-line\">Defibrillator/AED available early</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Lignocaine 100mg IV bolus (can be repeated at 5 minutes)</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Likely ROSC with better perfusion of tissues with more off gasing of CO2</div><div class=\"answer-line\">Stop compressions and assess rhythm. If compatible with pulse feel for pulse.</div><div class=\"answer-line\">Nth Syd SAQ paper 2021.2</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">B – lung protective ventilation aiming for normal PaCO2/ETCO2 and O2 Sats 94-98%</div><div class=\"answer-line\">C- Maintain normal Rhythm – Amiodarone infusion, check electrolytes and correct abnormalities.</div><div class=\"answer-line\">Maintain normal BP – with inotropes as necessary</div><div class=\"answer-line\">Consider invasive monitoring</div><div class=\"answer-line\">D – Start sedation and consider muscle relaxant</div><div class=\"answer-line\">E – Investigation: ECG ABG and CXR</div><div class=\"answer-line\">Normothermia</div><div class=\"answer-line\">Consider most appropriate place for transfer -  Cath lab/ICU/CT</div><div class=\"answer-line\">Nth Syd SAQ paper 2021.2</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":6,"title":"","stemText":"A 32-year-old female, who is two weeks postpartum, presents to your ED with left breast erythema, pain and swelling. She reports 1-day history of fever and rigors. The patient is exclusively breastfeeding her baby. She has had a previous anaphylactic reaction to penicillin.","parts":[{"id":"a","label":"Part A","prompt":"List three (3) contributing factors to the development of lactational mastitis. (3 marks)"},{"id":"b","label":"Part B","prompt":"List two non-pharmacological treatments that you would suggest for this patient (2 marks)"},{"id":"c","label":"Part C","prompt":"Complete the table with two (2) pharmacological treatments that you would prescribe for this patient, including doses. For each medication listed, include any known potential adverse effects that the patient should observe their infant for (4 marks) Medication Potential adverse effects in infant"},{"id":"d","label":"Part D","prompt":"The patient is discharged home, but returns to ED two days later with ongoing symptoms. What are the next steps in your assessment and management of this patient? (3 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Poor infant positioning</div><div class=\"answer-line\">•</div><div class=\"answer-line\">Milk stasis</div><div class=\"answer-line\">•</div><div class=\"answer-line\">Nipple damage</div><div class=\"answer-line\"><strong>ii.</strong><strong> </strong></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Frequent breast emptying – breastfeeding does not need to be interrupted</td></tr><tr><td>•</td><td>Routine hand washing prior to breast manipulation</td></tr><tr><td>•</td><td>Referral to Lactation Consultant to assist with breastfeeding technique</td></tr><tr><td><strong>iii.</strong><strong> </strong></td><td><strong>Complete the table with two (2) pharmacological treatments that you would prescribe for </strong></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Clindamycin 450mg PO q8h for</td><td>Diarrhoea, vomiting, skin rash or thrush. Less commonly,</td></tr><tr><td>5 days</td><td>bloody stools.</td></tr><tr><td>(Only one correct option required to gain 1 mark)</td><td></td></tr><tr><td>Analgesia:</td><td>Safe to use – nil adverse effects</td></tr><tr><td>Paracetamol 1g qid prn OR</td><td></td></tr><tr><td>Ibuprofen 400mg tds prn OR</td><td></td></tr><tr><td>Diclofenac 50mg tds prn OR</td><td></td></tr><tr><td>Oxycodone 2.5-5mg q4h prn</td><td>Sedation, excessive drowsiness, poor feeding, sleeping pattern</td></tr><tr><td>changes</td><td></td></tr><tr><td>(Only one correct option required to gain 1 mark)</td><td></td></tr><tr><td><strong>ZERO SCORE</strong> for entire part of question if answer includes:</td><td></td></tr><tr><td>o Penicillin or cephalosporin given known anaphylaxis to penicillin</td><td></td></tr><tr><td>o Morphine/Codeine-containing formulations due to breastfed infant’s impaired capacity</td><td></td></tr><tr><td>to metabolise morphine</td><td></td></tr><tr><td><strong>iv.</strong><strong> </strong></td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Nth Syd SAQ paper 2021.2</div><div class=\"answer-line\">•</div><div class=\"answer-line\">Admit patient and commence IV antibiotics: clindamycin 600mg IV q8h</div><div class=\"answer-line\">•</div><div class=\"answer-line\">Consider alternative diagnoses eg. inflammatory cancer</div><div class=\"answer-line\">Nth Syd SAQ paper 2021.2</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":7,"title":"","stemText":"A two-month-old boy is rushed into your ED by his mother. He is mottled, grey and unresponsive to painful stimuli. He has been experiencing symptoms of gastroenteritis for the past two days but is otherwise a healthy baby His obs are as below:\n\nHR 180bpm\n\nBP 60/30\nCap refil 4 seconds\nO2 Sats 99%\n\nRR 32\n\nTemp 36degrees\nAn IVC is inserted and a full set of bloods and VBG is obtained. A bolus of 10mls/kg N/Saline is immediately given\n\nVBG\n\npH 7.18\n\npCO2 39\n\npO2 31\n\nHCO3 14\n\nBE -13.2\n\nNa 125\n\nK 8.3\n\nCl 94\n\nGlucose 3.0\n\nLactate 4.8\n\nHb 154","parts":[{"id":"a","label":"Part A","prompt":"Describe and interpret the VBG above (4 marks)"},{"id":"b","label":"Part B","prompt":"List 3 other blood tests you might send. Provide a brief justification (3 marks)"},{"id":"c","label":"Part C","prompt":"Based on the VBG, describe your management of this baby (6 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><em>Severe metabolic acidosis – AG = 125 – (14 + 94) = 17 -&gt; HAGMA </em></div><div class=\"answer-line\"><em>Expected CO2 = 1.5 (14) + 8 = 29, concomitant respiratory acidosis – likely related to the drowsiness, </em></div><div class=\"answer-line\"><em>hypoventilation, unable to compensate </em></div><div class=\"answer-line\"><em>Delta ratio = 17-12/24-14 = 5/10 = 0.5 = high and normal metabolic acidosis  </em></div><div class=\"answer-line\"><em>Low sodium and high potassium – think endocrine -&gt; CAH. Likely mineralocorticoid deficiency </em></div><div class=\"answer-line\"><em>Lactate high – HAGMA – sepsis / pre-renal failure – would be good to see urea as this may be adding </em></div><div class=\"answer-line\"><em>to HAGMA </em></div><div class=\"answer-line\"><em>NAGMA likely secondary to bicarb losses from GI (diarrhoea / vomiting) or renal (uraemic acidosis). </em></div><div class=\"answer-line\"><em>May have developed RTA type 4 (although chloride normal and bicarb low) but is associated with </em></div><div class=\"answer-line\"><em>addison’s disease / aldosterone deficiency </em></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Cortisol</td></tr><tr><td>•</td><td>ACTH</td></tr><tr><td>•</td><td>17 hydroxyprogesterone</td></tr><tr><td>•</td><td>Plasma renin activity</td></tr><tr><td>•</td><td>FBC/CRP ?sepsis</td></tr><tr><td>•</td><td>BC ? sepsis</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><em>Very unwell, early involvement of paediatrics and retrieval if needed </em></div><div class=\"answer-line\"><em>Further 10mls/kg N/Saline aim to optimise haemodynamics and improve electrolytes. If BP and cap </em></div><div class=\"answer-line\"><em>refil not improving will need adrenaline / NAd infusion. Aim SBP 80mmHg and cap refil &lt;3 seconds </em></div><div class=\"answer-line\"><em>Second IVC – 25mg hydrocortisone, this can be repeated if little response. Will need regular 6 hourly </em></div><div class=\"answer-line\"><em>10mg hydrocortisone </em></div><div class=\"answer-line\">Nth Syd SAQ paper 2021.2</div><div class=\"answer-line\"><em>Cardiac monitor and ECG – treat hyperkalaemia with calcium gluconate 0.5ml/kg 10% over 15 </em></div><div class=\"answer-line\"><em>minutes, insulin 0.1U/kg / dex 10% 5ml/kg (caution as this can worsen the hyponatraemia), </em></div><div class=\"answer-line\"><em>salbutamol neb 2.5mg and consider bicarb 8.4% 1mmol/ml – 1ml/kg if pH not improving </em></div><div class=\"answer-line\"><em>Urgent antibiotics – treat as sepsis, unknown source </em></div><div class=\"answer-line\"><em>Monitor CO2 – if continues to rise, baby more drowsy </em><em> intubation/hyperventilation </em></div><div class=\"answer-line\"><em>Will need repeat EUCs to monitor Na and K </em></div><div class=\"answer-line\"><em>Careful monitor of glucose (currently does not need treatment) </em></div><div class=\"answer-line\"><em>Will need paediatric ICU – may require haemodialysis </em></div><div class=\"answer-line\">Nth Syd SAQ paper 2021.2</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":8,"title":"","stemText":"A 64-year-old male is brought to your ED via ambulance after a witnessed seizure on the street. You recognise him as a patient who frequently presents to your Emergency Department with alcohol intoxication. The paramedics report his generalised tonic clonic seizure stopped en route and he has normal vitals signs except for a Glascow Coma Score of 10 (E3/V2/M5).","parts":[{"id":"a","label":"Part A","prompt":"List your 6 most likely differentials for his reduced GCS (4 marks)\nBefore your initial pathology and imaging investigations return, he wakes and starts ranting about wanting to leave and pushes your nurse aside in order to get out."},{"id":"b","label":"Part B","prompt":"What are your priorities in managing this incident as senior clinician in charge of this patient? (5 marks) He ends up staying in your ED. You find out in the eMR he is prone to alcohol withdrawal seizures."},{"id":"c","label":"Part C","prompt":"Complete the table of three medications used in the ED for prevention/management of alcohol withdrawal seizures (6 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Post-ictal</td></tr><tr><td>-</td><td>Trauma related to seizure eg. SDH/ICH</td></tr><tr><td colspan=\"2\"><strong>Additional: (0.5 each, up to 2 marks) </strong></td></tr><tr><td>-</td><td>Ongoing/recurrent seizure (including non-convulsive status, alcohol withdrawal/seizures)</td></tr><tr><td>-</td><td>Medication administered by paramedics (for seizure termination)</td></tr><tr><td>-</td><td>Metabolic: hypoglycaemia, Alcoholic/starvation ketosis, hyponatraemia, Wernickes</td></tr><tr><td>-</td><td>Sepsis: neuro – encephalitis/meningitis, septic shock</td></tr><tr><td>-</td><td>Toxicology: EtOH intoxication, alcohol poisoning, other poisons/self harm, drug withdrawal</td></tr><tr><td>-</td><td>Other: space occupying lesion, other causes of reduced GCS unrelated</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Ensure nurse OK/safe/notify their team leader/ delegate someone to provide attention as</td></tr><tr><td colspan=\"2\">required</td></tr><tr><td>-</td><td>Ensure patient safety, detain patient under Duty of Care (as not safe to leave in current state</td></tr><tr><td colspan=\"2\">and need time to assess competency)</td></tr><tr><td colspan=\"2\"><strong>Additional: (0.5 each, up to 2 marks) </strong></td></tr><tr><td>-</td><td>Stratify risk</td></tr><tr><td>-</td><td>Ensure safety of other patients/staff in department</td></tr><tr><td>-</td><td>Verbal de-escalation</td></tr><tr><td>-</td><td>Engage in open communication/understand point of view of patient (carer for a pet/family</td></tr><tr><td colspan=\"2\">member)/show empathy/offer sandwich-drink</td></tr><tr><td>-</td><td>Code Black/Call for help/show of force</td></tr><tr><td>-</td><td>May need restraint – least restrictive possible: chemical vs physical</td></tr><tr><td>-</td><td>Need to complete assessment : clinical issues</td></tr><tr><td colspan=\"2\">Nth Syd SAQ paper 2021.2</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><strong>Dose/Administration route </strong></div><div class=\"answer-line\"><strong>2 marks per drug for correct answer/information </strong></div><div class=\"answer-line\">Diazepam – prevention of withdrawal seizures – 10-20mg orally every 2 hours for acute withdrawal,</div><div class=\"answer-line\">according to AWS, until symptoms subside</div><div class=\"answer-line\">Oxazepam – prevention of seizures in liver failure – 15-30mg orally every 2 hours for acute</div><div class=\"answer-line\">withdrawal, according to AWS, until symptoms subside</div><div class=\"answer-line\">Midazolam – treatment of seizures – 5-10mg IV/IM boluses</div><div class=\"answer-line\">Diazepam – treatment of seizures – 5-10mg IV/IM boluses</div><div class=\"answer-line\">RSI and Propofol/thiopentone – treatment of status, second line after benzos – RSI dose</div><div class=\"answer-line\">?Phenobarbitone – treatment of status, second line after benzos -</div><div class=\"answer-line\">? Levetiracetam – treatment of status, third line – 60mg/kg loading</div><div class=\"answer-line\">Phenytoin not advised for treatment of seizures</div><div class=\"answer-line\">Thiamine – prevention of Wernicke’s encephalopathy rather than seizures – 300mg IV/IM daily for 3-</div><div class=\"answer-line\">5 days, then orally thereafter</div><div class=\"answer-line\">Nth Syd SAQ paper 2021.2</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":9,"title":"","stemText":"A 60-year-old female is brought in by ambulance, following a low speed motor vehicle accident. The paramedics state no damage to either vehicle, appears patient reversed into a car in the carpark. Pt is confused and unable to recall event. She is repetitive with her questions and states she feels she is in a dream and has been seeing this incident replay over the past 3 days - almost like a deja-vu. She has no apparent injury\nHer observations are all within normal range. She is afebrile.\nShe has a background history of schizophrenia. She is on Zyprexa 7.5mg and has been taking this for 15 years.","parts":[{"id":"a","label":"Part A","prompt":"What important factors are needed from her history? (5 marks) Your assessment reveals no injuries and no other abnormal examination findings. She remains confused and this appears to be quite acute onset."},{"id":"b","label":"Part B","prompt":"What investigations would you perform next in ED and why? (4 marks)"},{"id":"c","label":"Part C","prompt":"What are the differences between delirium and acute psychosis? (5 marks) Characteristic Delirium Acute psychosis Onset\n\nVital signs\nPrior psychiatric history Course Cognition function Orientation Attention Concentration Hallucinations Speech Course All investigations are normal. She is admitted under the neurology team for an EEG and an MRI. It is believed she may have had a seizure."},{"id":"d","label":"Part D","prompt":"What discharge advice should this patient been given? (2 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">History – from husband / family – how she was that day. Course of illness. Any unwell contacts</div><div class=\"answer-line\">History from patient – what she can remember about incident / day</div><div class=\"answer-line\">History from psychologist / GP in regards mental health</div><div class=\"answer-line\">Symptoms from patient – headache / neck stiffness / signs of meningitis / encephalitis. Any</div><div class=\"answer-line\">neurological signs or symptoms to suggest SOL</div><div class=\"answer-line\">DHx - Any drugs taken / withdrawing from</div><div class=\"answer-line\">SHx – alcohol / illicit drugs</div><div class=\"answer-line\">Weight loss / heat intolerance – thyroid / endocrine issues</div><div class=\"answer-line\">Think causes of delirium – I WATCH DEATH – Infectious, withdrawal, acute metabolic, trauma, CNS</div><div class=\"answer-line\">disease, Hypoxia, Deficiencies, Environmental, Acute vascular, Toxins / drugs, Heaby metals</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Bedside – BSL – hypoglycaemia – confusion</div><div class=\"answer-line\">VBG - Na</div><div class=\"answer-line\">ECG – drug overdose</div><div class=\"answer-line\">CXR – septic screen</div><div class=\"answer-line\">UA – septic screen</div><div class=\"answer-line\">CTB – trauma / SOL</div><div class=\"answer-line\">LP – encephalitis</div><div class=\"answer-line\">EUC – Na, K</div><div class=\"answer-line\">FBC – infection</div><div class=\"answer-line\">CRP – infectious cause</div><div class=\"answer-line\">LFT – encephalopathy</div><div class=\"answer-line\">Blood alcohol / paracetamol</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>Characteristic</td><td>Delirium</td><td>Acute psychosis</td></tr><tr><td>Onset</td><td>Acute</td><td>Acute</td></tr><tr><td>Vital signs</td><td>Typically abnormal (fever,</td><td>Normal</td></tr><tr><td colspan=\"3\">tachycardia)</td></tr><tr><td>Prior psychiatric history</td><td>Uncommon</td><td>Common</td></tr><tr><td>Course</td><td>Rapid fluctuating</td><td>Stable</td></tr><tr><td><em>Cognition function </em></td><td>X</td><td>X</td></tr><tr><td>Orientation</td><td>Impaired</td><td>Occasionally impaired</td></tr><tr><td>Attention</td><td>Impaired</td><td>Disorganised</td></tr><tr><td>Concentration</td><td>Impaired</td><td>Impaired</td></tr><tr><td>Hallucinations</td><td>Visual, auditory</td><td>Auditory</td></tr><tr><td>Speech</td><td>Pressured, slow, incoherent</td><td>Coherent</td></tr><tr><td colspan=\"3\">Nth Syd SAQ paper 2021.2</td></tr><tr><td>Course</td><td>Typically reoslves</td><td>Responds to therapy,</td></tr><tr><td colspan=\"3\">recurrence common</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Follow up plan</div><div class=\"answer-line\">Safety netting</div><div class=\"answer-line\">Safety at home</div><div class=\"answer-line\">Driving advice</div><div class=\"answer-line\">Avoidance of alcohol / stimulants</div><div class=\"answer-line\">Nth Syd SAQ paper 2021.2</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":10,"title":"","stemText":"An 8-year-old male presents to Emergency Department with ongoing abdominal pain following\nfalling from his bike 2 days ago. His vital signs are normal except for temperature of 38.6. He has anorexia and vomiting for the last 36hrs. On examining his abdomen you note a contusion on his epigastium (below) and tenderness across all quadrants.","parts":[{"id":"a","label":"Part A","prompt":"Describe and interpret the picture (2 Marks)"},{"id":"b","label":"Part B","prompt":"List your differential for this patient (4 Marks)"},{"id":"c","label":"Part C","prompt":"Discuss imaging options in this patient (6 Marks)"},{"id":"d","label":"Part D","prompt":"List the anatomical differences responsible for the injury pattern seen in traumatic abdominal injuries in the paediatric population (4 Marks)"}],"propPages":["asset:img2e9e2ab6d237bd6eff"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Circular contusion of age consistent with trauma 2 days ago</div><div class=\"answer-line\">Clinical concern for handlebar injury</div><div class=\"answer-line\">Nth Syd SAQ paper 2021.2</div><div class=\"answer-line\"><strong>ii.</strong><strong> </strong></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Trauma – <strong>Solid organ</strong> – Spleen &gt; Liver &gt; Kidneys &gt; Pancreas. <strong>Hollow</strong> – Duodenum &gt; Ileum &gt;</div><div class=\"answer-line\">Large Bowel. <strong>Vascular injuries</strong></div><div class=\"answer-line\"><strong>Non Trauma</strong> – Appendicitis  / UTi / GE  (1 for each <strong>Bold</strong>)</div><div class=\"answer-line\"><strong>iii.</strong><strong> </strong></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">3 modalities should be discussed with relative pro / con scoring 1 each, totaling 2 per</div><div class=\"answer-line\">modality. <strong>Must discuss CT</strong>.</div><div class=\"answer-line\">CT – Gold standard imaging / Aids in treatment conservative vs surgical / Identifies non-</div><div class=\"answer-line\">traumatic causes = Requires transfer from ED / Ionising</div><div class=\"answer-line\">XR – Rapid / Available / Identifies perforation in dept = Does not assess any other injuries</div><div class=\"answer-line\">USS – No radiation / Available / Good for solid organ injury / Identifies free fluid / Identifies</div><div class=\"answer-line\">non-traumatic injury in this case = Negative study does not exclude injury / Does not assess</div><div class=\"answer-line\">bowel</div><div class=\"answer-line\">POCUS – Bedside / Rapid / Reproducible = User dependent / <strong>Not validated in paediatric </strong></div><div class=\"answer-line\"><strong>population </strong></div><div class=\"answer-line\"><strong>iv.</strong><strong> </strong></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\"><strong>1 for each</strong>: Thin abdominal wall (muscle + fat) providing less protection / More pliable ribs</div><div class=\"answer-line\">providing less protection / Liver and spleen take up a larger proportion of abdominal cavity /</div><div class=\"answer-line\">The diaphragm is more horizontal, pushing the spleen and liver below the rib cage / Bladder</div><div class=\"answer-line\">in babies intra abdominal / Adult protection systems (seatbelts) often fitted incorrectly</div><div class=\"answer-line\">causing abdominal injury</div><div class=\"answer-line\">Nth Syd SAQ paper 2021.2</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":11,"title":"","stemText":"You are the retrieval doctor based in a large city. You have been notified of a primary tasking to a\nstabbing 5 minutes flight time away.\nScene report: Two patients, one located outside the residence, a 22-year-old female with multiple stab wounds to the chest and abdomen. The second patient is a 22-year-old male located inside the residence who is alleged to have stabbed the female patient before stabbing himself in the chest. He has arrested and is receiving CPR. You arrive on scene 10 minutes later and see the female patient lying in the garden, groaning in extremis, appearing pale with paramedics attempting to gain access and multiple bystanders around her. CPR is ongoing with the male patient, current downtime of approximately 10-20 minutes. You are the only medical team, with the resources to manage only 1 patient.","parts":[{"id":"a","label":"Part A","prompt":"List six (6) difficulties you may encounter in providing medical care in the pre- hospital environment. (6 marks)"},{"id":"b","label":"Part B","prompt":"State which patient you will allocate your resources to and your rationale (2 marks) The male patient is declared deceased. The female patient has a patent airway, sats 84% on non-rebreather, evidence of a left haemopneumothorax on US, a palpable central pulse but no radial, HR 140. GCS E3V2M5 (10). You carry 3 units of blood and will be transporting her by road for 20 minutes to the nearest trauma centre."},{"id":"c","label":"Part C","prompt":"List two (2) interventions you will perform for this patient and six (6) OTHER prehospital interventions which have been shown to be of benefit when performed in the prehospital setting (8 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Unfamiliar environment - exposed to elements, variable light, noisy, terrain rough and</td></tr><tr><td colspan=\"2\">uneven</td></tr><tr><td>•</td><td>Distressed, intoxicated or angry family members / bystanders</td></tr><tr><td>•</td><td>Working on casualties on the ground</td></tr><tr><td>•</td><td>Hazards of incident</td></tr><tr><td>•</td><td>Site appears disorganised</td></tr><tr><td>•</td><td>Information unavailable, inconsistent or incorrect</td></tr><tr><td>•</td><td>Inadequate staff, equipment, resources</td></tr><tr><td colspan=\"2\">• Different hierarchical systems</td></tr><tr><td colspan=\"2\"><strong>ii.</strong><strong> </strong></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Patient: Can make arguments for either, needs to have sensible rationale. Female patient</div><div class=\"answer-line\">seems the more obvious choice</div><div class=\"answer-line\">Rationale: Male patient has close to zero chance of survival given his prolonged down</div><div class=\"answer-line\">time, would be at the limits of indication for resuscitative thoracotomy. Female patient</div><div class=\"answer-line\">has much better chance and so resources should be used on her.</div><div class=\"answer-line\">Nth Syd SAQ paper 2021.2</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">For this patient:</td></tr><tr><td>•</td><td>Left sided finger (+/- tube) thoracostomy</td></tr><tr><td>•</td><td>Blood transfusion</td></tr><tr><td>•</td><td>Argument can be made for RSI (essential if only doing a finger thoracostomy)</td></tr><tr><td colspan=\"2\">In general:</td></tr><tr><td>•</td><td>Analgesia</td></tr><tr><td>•</td><td>Pelvic binding</td></tr><tr><td>•</td><td>Femoral traction</td></tr><tr><td>•</td><td>CPR</td></tr><tr><td>•</td><td>Early defib (1min delay = 10% incr mortality)</td></tr><tr><td>•</td><td>Needle decompression of pneumothorax</td></tr><tr><td>•</td><td>Basic airway</td></tr><tr><td>•</td><td>Nitrates/GTN in LVF (improves recovery and mortality)</td></tr><tr><td>•</td><td>Thrombolytics for MI with long transport time (decr time to thrombolysis by 30-45mins; 15-</td></tr><tr><td colspan=\"2\">30% false positives, 5% false negatives)</td></tr><tr><td>•</td><td>RSI if long transport time (if not mentioned above)</td></tr><tr><td>•</td><td>ECG pre-hospital (get ECG 30mins earlier, show dynamic changes; adds 5mins to scene time)</td></tr><tr><td>•</td><td>Resuscitative thoracotomy (controversial however data from London HEMS suggests</td></tr><tr><td colspan=\"2\">increased survival)</td></tr><tr><td>•</td><td>Emergency amputation – for extraction from a life-threatening scene when trapped with a</td></tr><tr><td colspan=\"2\">devitalised limb</td></tr><tr><td>•</td><td>Escharotomies if long transport time to ED / burns centre</td></tr><tr><td colspan=\"2\">Nth Syd SAQ paper 2021.2</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":12,"title":"","stemText":"A 72 year old female presents with jaw pain and inability to close her mouth after yawning. After examining her, you diagnose anterior TMJ dislocation.","parts":[{"id":"a","label":"Part A","prompt":"List three risk factors for this problem. (3 marks)"},{"id":"b","label":"Part B","prompt":"List three mechanisms that can cause this problem. (3 marks)"},{"id":"c","label":"Part C","prompt":"Describe two techniques for reduction (no need to describe analgesia/anaesthesia) (6 marks)"},{"id":"d","label":"Part D","prompt":"Superior and posterior TMJ dislocations are rare. For each list one specific complication (2 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Temporomandibular ligament laxity due to Ehler Danlos or Marfan syndrome</div><div class=\"answer-line\">•</div><div class=\"answer-line\">Previous TMJ dislocation  acquired laxity</div><div class=\"answer-line\">•</div><div class=\"answer-line\">Anatomic mismatch between the fossa and articular eminence</div><div class=\"answer-line\"><strong>ii.</strong><strong> </strong></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Iatrogenic: Dental procedures, laryngoscopy</td></tr><tr><td>•</td><td>Extreme mouth opening - yawning, eating, vomiting</td></tr><tr><td>•</td><td>Dystonic drug reaction</td></tr><tr><td>•</td><td>Seizures</td></tr><tr><td>•</td><td>Tetanus</td></tr><tr><td>•</td><td>Trauma</td></tr><tr><td colspan=\"2\"><strong>iii.</strong><strong> </strong></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\"><strong>Traditional</strong>: Patient seated with head supported posteriorly. Physician stands in front with</td></tr><tr><td colspan=\"2\">elbows flexed. Mandible held with gloved thumbs intraorally just lateral to lower molars.</td></tr><tr><td colspan=\"2\">Down and backward manipulation</td></tr><tr><td>•</td><td><strong>Modified traditional</strong>. Physician stands behind the patient with hands in the same position.</td></tr><tr><td colspan=\"2\">Down and backwards pressure from thumbs</td></tr><tr><td>•</td><td><strong>Syringe</strong>: Reduce one side at a time. 5 or 10ml syringe between posterior upper and lower</td></tr><tr><td colspan=\"2\">molars. Patient bites down on syringe whilst it is rolled back and forth between the teeth</td></tr><tr><td colspan=\"2\">until reduced. Typically other side reduces spontaneously</td></tr><tr><td>•</td><td><strong>Wrist pivot</strong>: Physician faces patient, grasps mandible with thumbs under chin and fingers on</td></tr><tr><td colspan=\"2\">occlusal surfaces lower molars. Upward force with thumbs and downward pressure by</td></tr><tr><td colspan=\"2\">fingers. Pivots wrists forwards</td></tr><tr><td>•</td><td><strong>Gag</strong>: Elicit gag reflex and reflex inhibition of muscles may result in relocation. Beware</td></tr><tr><td colspan=\"2\">vomiting</td></tr><tr><td colspan=\"2\">Nth Syd SAQ paper 2021.2</td></tr><tr><td colspan=\"2\"><strong>iv.</strong><strong> </strong></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Both are usually associated with high-energy trauma</td><td></td></tr><tr><td>•</td><td>Superior – mandibular fossa fracture</td></tr><tr><td>•</td><td>Posterior – fracture of the temporal bone or external auditory canal</td></tr><tr><td>Nth Syd SAQ paper 2021.2</td><td></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":13,"title":"","stemText":"A 45-year-old man presents to your ED with a sudden-onset, severe occipital headache and neck pain, which occurred while bench pressing at the gym five hours ago. You suspect he has a subarachnoid haemorrhage.","parts":[{"id":"a","label":"Part A","prompt":"What is the sensitivity and specificity of third-generation CT for subarachnoid haemorrhage in this patient? (2 marks)"},{"id":"b","label":"Part B","prompt":"List three (3) factors that may reduce the sensitivity of CT for subarachnoid haemorrhage. (3 marks) A CT brain is performed, which is normal. You remain concerned about the possibility of a subarachnoid haemorrhage being the cause of this patient’s headache."},{"id":"c","label":"Part C","prompt":"Complete the table with one (1) advantage and two (2) disadvantages of the performing a lumbar puncture or CT angiography to assess for subarachnoid haemorrhage in this patient. (6 marks) Lumbar puncture CT angiography"},{"id":"d","label":"Part D","prompt":"In addition to the normal CT brain, list two (2) criteria from the lumbar puncture results that must be satisfied in order to reliably exclude subarachnoid haemorrhage. (2 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">98.5% sensitivity (97-100%)</div><div class=\"answer-line\">•</div><div class=\"answer-line\">99.5% specificity</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">ii.</div><div class=\"answer-line\">Increasing time after onset of symptoms</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Option</th><th>Advantage</th><th>Disadvantage</th></tr></thead><tbody><tr><td>Non-expert radiologist interpretation</td><td></td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"4\">Small volume bleed</td></tr><tr><td>v.</td><td>Atypical symptoms</td><td></td><td></td></tr><tr><td colspan=\"4\">A CT brain is performed, which is normal. You remain concerned about the possibility of a</td></tr><tr><td colspan=\"4\">subarachnoid haemorrhage being the cause of this patient’s headache.</td></tr><tr><td><strong>iii.</strong><strong> </strong></td><td><strong>Complete the table with one (1) advantage and two (2) disadvantages of the performing a </strong></td><td></td><td></td></tr><tr><td colspan=\"4\"><strong>lumbar puncture or CT angiography to assess for subarachnoid haemorrhage in this patient. (6 </strong></td></tr><tr><td colspan=\"4\"><strong>marks) </strong></td></tr><tr><td><strong>Lumbar puncture </strong></td><td><strong>CT angiography </strong></td><td></td><td></td></tr><tr><td>Advantages:</td><td>Advantages:</td><td></td><td></td></tr><tr><td>•</td><td>Able to identify other causes of headache</td><td>•</td><td>Non-invasive</td></tr><tr><td colspan=\"4\">eg. meningitis</td></tr><tr><td>Disadvantages:</td><td>Disadvantages:</td><td></td><td></td></tr><tr><td>•</td><td>Post-lumbar puncture headache</td><td>•</td><td>Detection of incidental aneurysms</td></tr><tr><td>•</td><td>Must be performed 12hrs from</td><td>prompting unnecessary intervention</td><td></td></tr><tr><td>haemorrhage onset</td><td>•</td><td>Additional radiation</td><td></td></tr><tr><td>•</td><td>Time-consuming</td><td>•</td><td>Risk of IV contrast administration</td></tr><tr><td>•</td><td>Can be technically difficult – body habitus</td><td></td><td></td></tr><tr><td>•</td><td>Possibility of equivocal result (traumatic</td><td></td><td></td></tr><tr><td colspan=\"4\">tap)</td></tr><tr><td colspan=\"4\">A subsequent lumbar puncture is performed.</td></tr><tr><td colspan=\"4\">Nth Syd SAQ paper 2021.2</td></tr><tr><td><strong>iv.</strong><strong> </strong></td><td><strong>In addition to the normal CT brain, list two (2) criteria from the lumbar puncture results that </strong></td><td></td><td></td></tr><tr><td colspan=\"4\"><strong>must be satisfied in order to reliably exclude subarachnoid haemorrhage. (2 marks) </strong></td></tr><tr><td>•</td><td>Absence of xanthochromia</td><td></td><td></td></tr><tr><td>•</td><td>Zero or few RBCs (&lt;5 x 106 RBCS/L)</td><td></td><td></td></tr><tr><td colspan=\"4\">Nth Syd SAQ paper 2021.2</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":14,"title":"","stemText":"You are the Consultant in charge at a Regional hospital. A 17-year-old girl is brought in by her parents with a 6-month history of weight loss. She is complaining of weakness and palpitations.\n\nVital signs BP 90/65 PR 60 SpO2 99% RA temp 36.","parts":[{"id":"a","label":"Part A","prompt":"Outline 4 features on history and 3 features on examination pertinent to this case (7\nmarks) History Exam"},{"id":"b","label":"Part B","prompt":"You request an ECG. List 4 ECG features that would suggest hypokalaemia (4 marks)\nVenous blood gas shows a serum K of 2.2. Her clinical assessment is consistent with anorexia nervosa and ventricular ectopics."},{"id":"c","label":"Part C","prompt":"What options are available to replace the potassium? Include the dose and give pros and cons for each (4 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">History</td></tr><tr><td>•</td><td><strong>Eating history/diary-esp anorexia and bulimia </strong></td></tr><tr><td>•</td><td><strong>Weight hx-</strong>loss and fluctuations</td></tr><tr><td>•</td><td>Vomiting or diarrhoea</td></tr><tr><td>•</td><td>Exercise history</td></tr><tr><td>•</td><td>Menstrual history</td></tr><tr><td>•</td><td>Drugs causing low k-diuretics/bronchodilators/laxatic=ves/D and A</td></tr><tr><td>•</td><td>Collaborative history from family</td></tr><tr><td>•</td><td><strong>Psych history/SI/risk </strong></td></tr><tr><td colspan=\"2\">Exam</td></tr><tr><td>•</td><td>Signs for possible eating disorder- body hair/down; teeth for enamel loss from vomiting; skin</td></tr><tr><td colspan=\"2\">sores</td></tr><tr><td>•</td><td><strong>Evidence of self harm </strong></td></tr><tr><td>•</td><td><strong>Height weight/BMI </strong></td></tr><tr><td>•</td><td><strong>CVS signs of autonomic instability and heart failure </strong></td></tr><tr><td>•</td><td>Neuro exam hyporeflexia and general weakness</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Increased p wave amplitude</td></tr><tr><td>•</td><td>Prolonged pr interval</td></tr><tr><td>•</td><td>Widespread ST depression and T wave flattening/inversion</td></tr><tr><td>•</td><td>Prominent U waves best seen in praecordial leads V2-V3</td></tr><tr><td>•</td><td>Apparent long QT interval (merging of T with U wave)</td></tr><tr><td>•</td><td>Worsening hypokalaemia supraventricular and ventricular ectopics</td></tr><tr><td>•</td><td>Supraventricular tachyarrythmias (af, atrial flutter, atrial tachycardia)</td></tr><tr><td>•</td><td>Potential to develop life threatening ventricular arrythmias (VT/VF/Torsades)</td></tr><tr><td colspan=\"2\">Nth Syd SAQ paper 2021.2</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td><strong>Oral </strong>Dose 40mmol every 6 hours.  Rapid absorption formula indicated (eg CHlovescent)</td><td><strong>Pros</strong> Avoids IV complications of rapid infusion and pain at IV site. May be more acceptable to</td></tr><tr><td>patient. Can be given via NG tube.</td><td><strong>Cons </strong>Unpleasant taste. Compliance in 17 yo girl with eating disorder maybe an issue</td></tr><tr><td>I<strong>V</strong> Dose max 40mmol/hr peripheral</td><td><strong>Pros</strong> Avoids compliance issue.  Can be titrated to repeat VBG meaurements.</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":15,"title":"","stemText":"A four-year-old boy is brought into your ED in a small costal town. Around 20 minutes ago he was playing in a rock pool and cried out. His mother couldn’t find any injury and he quickly settled down, saying he was playing with an octopus and it bit him. Shortly after he developed vomiting. His mother has carried him into ED. She is screaming for help. He is obtunded in her arms with central cyanosis.\nHis observations are as follows:\n\nHR 53\nWeakly palpable central pulse. Radial pulses unpalpable.\n\nSats - unable to get an accurate trace / unrecordable\nNo spontaneous breaths\n\nGCS 3, pupils fixed and dilated","parts":[{"id":"a","label":"Part A","prompt":"Name one (1) of the toxins produced by this octopus and state its mechanism of action (2 marks) You successfully intubate the child."},{"id":"b","label":"Part B","prompt":"List five (5) post-intubation management priorities (5 marks)"},{"id":"c","label":"Part C","prompt":"Complete the following table of marine animals with a brief description of the typical clinical picture of severe envenomation (5 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Tetrodotoxin</div><div class=\"answer-line\">Na+ channel blocking neurotoxin</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Nth Syd SAQ paper 2021.2</div><div class=\"answer-line\"><strong>Sedation (need drugs, doses/rates) – blue ringed octopus venom does not affect conscious </strong></div><div class=\"answer-line\"><strong>level </strong></div><div class=\"answer-line\"><strong>Activate retrieval service – needs to be retrieved to PICU </strong></div><div class=\"answer-line\">Contact PICU</div><div class=\"answer-line\">Ongoing fluid resuscitation</div><div class=\"answer-line\">Support for Mum – nurse or social work if available</div><div class=\"answer-line\">Any other reasonable inc. CXR, NGT, ventilator settings, fluids etc</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>Stonefish</td><td>Immediate excruciating pain, may cause weakness /</td></tr><tr><td colspan=\"2\">paralysis, CV collapse</td></tr><tr><td>Puffer fish (ingestion)</td><td>Descending flaccid paralysis, respiratory failure arrythmias</td></tr><tr><td>Sea snake</td><td>Bites may not cause pain. Descending paralysis and myolysis</td></tr><tr><td>Cone snail</td><td>Immediate pain then numbness at the site. Progressive</td></tr><tr><td colspan=\"2\">paralysis</td></tr><tr><td>Platypus</td><td>Immediate severe disabling pain and hyperaesthesia</td></tr><tr><td colspan=\"2\">Nth Syd SAQ paper 2021.2</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":16,"title":"","stemText":"A 25-year-old female has been sent by her GP with chest pain 4 days after her 2nd Pfizer COVID-19 vaccination and a provisional diagnosis of vaccine-induced pericarditis.","parts":[{"id":"a","label":"Part A","prompt":"What are the typical clinical features of pericarditis chest pain? (3 marks)"},{"id":"b","label":"Part B","prompt":"List 4 other causes of pericarditis? (4 marks)"},{"id":"c","label":"Part C","prompt":"The patient’s ECG is displayed. Describe the abnormalities. (2 marks)"},{"id":"d","label":"Part D","prompt":"What are the 4 stages of ECG changes? (4 marks)"},{"id":"e","label":"Part E","prompt":"What two drug treatments will you prescribe? (4 marks)"}],"propPages":["asset:img84771d17c51280be28"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">-positional, typically worse lying flat and relieved sitting forward</div><div class=\"answer-line\">-sharp, stabbing nature.</div><div class=\"answer-line\">- radiates to left trapezius ridge</div><div class=\"answer-line\">-associated with a rub</div><div class=\"answer-line\"><strong>ii.</strong><strong> </strong></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">-Infectious – mainly viral (e.g. coxsackie virus); occasionally bacterial, fungal, TB.</div><div class=\"answer-line\">-Immunological – SLE, rheumatic fever</div><div class=\"answer-line\">-Uraemia</div><div class=\"answer-line\">-myxoedema</div><div class=\"answer-line\">-Post-myocardial infarction or following cardiac surgery (Dressler’s syndrome)</div><div class=\"answer-line\">-Trauma</div><div class=\"answer-line\">-Paraneoplastic syndromes</div><div class=\"answer-line\">-Drug-induced (e.g. isoniazid, cyclosporin)</div><div class=\"answer-line\">-Post-radiotherapy</div><div class=\"answer-line\"><strong>iii.</strong><strong> </strong></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Widespread concave ST elevation and PR depression is present throughout the precordial (V2-6)</div><div class=\"answer-line\">and limb leads (I, II, aVL, aVF). There is reciprocal ST depression and PR elevation in aVR.</div><div class=\"answer-line\">Nth Syd SAQ paper 2021.2</div><div class=\"answer-line\"><strong>iv.</strong><strong> </strong></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\"><strong>Stage 1</strong> – widespread concave up STE and PR depression (with reciprocal changes in aVR) occurs</div><div class=\"answer-line\">during the first two weeks.</div><div class=\"answer-line\"><strong>Stage 2</strong> – normalisation of ST changes; generalised T wave flattening , 1 to 3 weeks.</div><div class=\"answer-line\"><strong>Stage 3</strong> – flattened T waves become inverted 3 to several weeks.</div><div class=\"answer-line\"><strong>Stage 4</strong> – ECG returns to normal, several weeks onwards, but TW may stay inverted.</div><div class=\"answer-line\">(Less than 50% of patients progress through all four classical stages and evolution of changes may</div><div class=\"answer-line\">not follow this typical pattern.)</div><div class=\"answer-line\"><strong>v.</strong><strong> </strong></div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\">Colchicine 500 mcg BD for 3 months</div><div class=\"answer-line\">-</div><div class=\"answer-line\">Plus -</div><div class=\"answer-line\">Ibuprofen 600 mg TDS for 1-2 weeks then taper</div><div class=\"answer-line\">-</div><div class=\"answer-line\">Or –</div><div class=\"answer-line\">Aspirin 750-1000 mg TDS for 1-2 weeks then taper</div><div class=\"answer-line\">Nth Syd SAQ paper 2021.2</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":17,"title":"","stemText":"A 25 year old man presents following a motorbike crash. He has an obvious injury to his left leg and you suspect a compartment syndrome.","parts":[{"id":"a","label":"Part A","prompt":"Apart from long bone fracture, list 6 causes of compartment syndrome (6 marks)"},{"id":"b","label":"Part B","prompt":"What are the typical clinical findings in compartment syndrome? (4 marks)"},{"id":"c","label":"Part C","prompt":"The anterior compartment of the lower leg is the most commonly affected compartment. List the neurological findings you might find in a severe anterior lower leg compartment syndrome. (2 marks)"},{"id":"d","label":"Part D","prompt":"Explain the use of “delta pressure” to diagnose compartment syndrome when pressures are directly measured using a needle/manometer device (3 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Acute extremity ischemia with reperfusion</div><div class=\"answer-line\">Burn injury</div><div class=\"answer-line\">Crush injury</div><div class=\"answer-line\">Spontaneous hemorrhage/hematoma</div><div class=\"answer-line\">Soft tissue infection</div><div class=\"answer-line\">Nontraumatic myositis/myonecrosis/rhabdomyolysis</div><div class=\"answer-line\">Systemic inflammatory response syndrome (SIRS)/massive fluid resuscitation</div><div class=\"answer-line\">High-pressure injection</div><div class=\"answer-line\">Intravenous extravasation injury</div><div class=\"answer-line\">Inadvertent/intentional intra-arterial injection</div><div class=\"answer-line\">Prolonged immobilization</div><div class=\"answer-line\">Venomous bites/stings</div><div class=\"answer-line\">Tight cast/splint/dressing</div><div class=\"answer-line\">Closure of fascial deficits</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Symptoms:</div><div class=\"answer-line\">Pain out of proportion to apparent injury (early and common finding)</div><div class=\"answer-line\">Persistent deep ache or burning pain</div><div class=\"answer-line\">Paresthesias</div><div class=\"answer-line\">Examination findings:</div><div class=\"answer-line\">Pain with passive stretch of muscles in the affected compartment (early finding)</div><div class=\"answer-line\">Tense compartment with a firm &quot;wood-like&quot; feeling</div><div class=\"answer-line\">Pallor from vascular insufficiency (uncommon)</div><div class=\"answer-line\">Diminished sensation</div><div class=\"answer-line\">Muscle weakness (onset within approximately two to four hours of ACS)</div><div class=\"answer-line\">Paralysis (late finding)</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">The anterior lower leg compartment contains the four extensor muscles of the foot, the</div><div class=\"answer-line\">anterior tibial artery, and the deep peroneal nerve. Signs of ACS affecting the anterior</div><div class=\"answer-line\">compartment include <strong>loss of sensation between the first (ie, great) and second toes</strong> and</div><div class=\"answer-line\"><strong>weakness of foot dorsiflexion</strong>. Late sequelae include foot drop, claw foot, and deep</div><div class=\"answer-line\">peroneal nerve dysfunction</div><div class=\"answer-line\">Nth Syd SAQ paper 2021.2</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Normal compartment pressure is 0-8 mmHg. Ischaemia occurs when tissue pressures</div><div class=\"answer-line\">approach diastolic blood pressure.</div><div class=\"answer-line\">Rather than using an absolute value of the measured compartment pressure to decide if</div><div class=\"answer-line\">fasciotomy is required, it is preferred to use a measure of perfusion pressure – the delta</div><div class=\"answer-line\">pressure</div><div class=\"answer-line\">The delta pressure = diastolic BP – measured compartment pressure</div><div class=\"answer-line\">A delta pressure &lt; 20-30 mmHg indicates need for fasciotomy</div><div class=\"answer-line\">Nth Syd SAQ paper 2021.2</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":18,"title":"","stemText":"An 87-year-old male presents 4 days after a bladder neck incision and cystoscopy.\nHe presents with severe scrotal and penile pain and redness which developed the day prior (see image). He is concerned now the colour has changed to burgundy and pain continues to increase. His suprapubic catheter is draining clear urine. He has a past history of type 2 diabetes, AF and BPH. He had been on anticoagulation with apixaban which was stopped 5 days prior to surgery. He has a long term SPC. He has no known allergies. He has temperature of 38.5, pulse 98, BP 122/55, normal WCC, Creatinine 188 (previously normal)\nand a CRP of 173.","parts":[{"id":"a","label":"Part A","prompt":"What are the important differential diagnoses? (2 Marks)"},{"id":"b","label":"Part B","prompt":"What clinical features would support the most concerning diagnosis? (6 Marks)"},{"id":"c","label":"Part C","prompt":"What are the principles of management of the most concerning diagnosis? (4 Marks)"},{"id":"d","label":"Part D","prompt":"What antibiotic treatment would you commence (3 Marks)? Provide route and dosing details"}],"propPages":["asset:img5ca6ba6afdeda64fc1"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Fourniers gangrene/necrotising skin &amp; soft tissue infection</div><div class=\"answer-line\">•</div><div class=\"answer-line\">Haematoma with superimposed infection/abscess</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">-constant severe pain;</div><div class=\"answer-line\">-bullae;</div><div class=\"answer-line\">-skin necrosis or bruising;</div><div class=\"answer-line\">-hard wooden subcut tissue;</div><div class=\"answer-line\">-cutaneous anaesthesia;</div><div class=\"answer-line\">-oedema beyond the margin of erythema</div><div class=\"answer-line\">-gas in the soft tissue manifested as crepitus or on imaging</div><div class=\"answer-line\">-systemic features of fever, raised wcc, elevated CRP, delirium, AKI</div><div class=\"answer-line\">-rapidly spreading infection,</div><div class=\"answer-line\">-haemodynamic instability</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">early aggressive surgical debridement</td></tr><tr><td>•</td><td>broad spectrum antibiotic cover</td></tr><tr><td>•</td><td>fluid resuscitation</td></tr><tr><td>•</td><td>inotropic/haemodynamic support</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Piperacillin-tazobactam 4.5g Q6-8 hourly  IV(Tazocin) or Meropneme 1g Q8 hrly or</div><div class=\"answer-line\">Ertapenem 1 g daily.  8 hourly acceptable due to the renal impairment</div><div class=\"answer-line\">•</div><div class=\"answer-line\">Vancomycin  IV 20-30g/kg loading dose then 15mg/k</div><div class=\"answer-line\">•</div><div class=\"answer-line\">Clindamycin  600-900mg Q 8 hourly IV or lincomycin 600mg Q 8 hourly IV</div><div class=\"answer-line\">o Reference CIAP antibiotic guidelines</div><div class=\"answer-line\">Nth Syd SAQ paper 2021.2</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":19,"title":"","stemText":"You are concerned about the large number of urine specimens from your department’s elderly patients being sent for culture. Many of them are returning a mixed growth and seem to have no clinical indication.","parts":[{"id":"a","label":"Part A","prompt":"Outline the steps in a quality improvement project to investigate your concern further (6 marks) Investigate reasoning behind specimens being sent Clinical audit with indications of specimens vs changing outcome investiate costs of urine specimens Provide education of importance of false positives and treating unnessarriy Create protocol for indications of urine specimens\nReevaluate protocol in 3/12"},{"id":"b","label":"Part B","prompt":"List 4 factors on history or examination that increase the pre-test probability of a UTI? (4 marks) History of dysuria New onset delirium\npresence of fever T 38.5 and Hypotension SBP >90\nHistory of recurrent UTI"},{"id":"c","label":"Part C","prompt":"What are 3 disadvantages of unnecessary antibiotic prescription? (3 marks)\nIncreasing antibiotic resistence unneccessary medication interaction increases other infections such as candida"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">**Answer should contain 5 points that aren’t too similar covering something along the lines of:</td></tr><tr><td>•</td><td>Working out how big a problem this is</td></tr><tr><td>•</td><td>Some sensible step to assess why this might be happening</td></tr><tr><td>•</td><td><strong>Some sensible step to address things we might change </strong></td></tr><tr><td>•</td><td>Involving some kind of stakeholder outside of ED doctors- nursing/geris etc</td></tr><tr><td>•</td><td>Looking for improvement/change</td></tr><tr><td colspan=\"2\">I don’t really care about listing steps with “quality cycle”-esque terms</td></tr><tr><td colspan=\"2\">Need to include at least how we might change (ie 1 bold point)</td></tr><tr><td colspan=\"2\">Very wordy “model” answer</td></tr><tr><td colspan=\"2\">1. Define the problem(s)- Audit to gather data on number of urine samples/indications/mixed</td></tr><tr><td colspan=\"2\">growth vs pure growth/significant results that impact management</td></tr><tr><td colspan=\"2\">2. What can we improve (diagnosis phase)- staff survey/prospective data collection over short</td></tr><tr><td colspan=\"2\">period of time</td></tr><tr><td colspan=\"2\">a. Method of collection a problem? Clean catch/in-out/catheter urines/how are</td></tr><tr><td colspan=\"2\">patients being educated to collect</td></tr><tr><td colspan=\"2\">b. Dubious clinical indication- initiated by ED? Aged care? Medical? Nursing? Allied</td></tr><tr><td colspan=\"2\">Health?</td></tr><tr><td colspan=\"2\">3. How can we improve (intervention phase)</td></tr><tr><td colspan=\"2\">a. Educate patients and staff re how to collect clean catch sample/limited utility of</td></tr><tr><td colspan=\"2\">permanent catheter for urine collection</td></tr><tr><td colspan=\"2\">b. Formulate agreed list of clinical indications- involve major stakeholders- GEM</td></tr><tr><td colspan=\"2\">physicians/geriatricians. Educate ED +/- Geriatric team about agreed indications</td></tr><tr><td colspan=\"2\">4. Evaluate impact- have we improved?- Audit to gather data on number of urine</td></tr><tr><td colspan=\"2\">samples/indications/mixed growth vs pure growth/significant results that impact</td></tr><tr><td colspan=\"2\">management post intervention</td></tr><tr><td colspan=\"2\">5. Repeat evaluation periodically to assess if improvement is sustained</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Nth Syd SAQ paper 2021.2</div><div class=\"answer-line\">Past medical Hx:</div><div class=\"answer-line\">Immunocompromise / Diabetes</div><div class=\"answer-line\">Cognitive impairment</div><div class=\"answer-line\">Immobility / Impairment in activities of daily living</div><div class=\"answer-line\">Renal tract pathology- Cystoceles, prostatic hypertrophy, recent instrumentation of urinary</div><div class=\"answer-line\">tract</div><div class=\"answer-line\">Prior antibiotic treatment for UTI</div><div class=\"answer-line\">Urinary incontinence</div><div class=\"answer-line\">Symptoms:</div><div class=\"answer-line\">Dysuria</div><div class=\"answer-line\">Urgency, frequency or new incontinence</div><div class=\"answer-line\">Flank pain</div><div class=\"answer-line\">Haematuria</div><div class=\"answer-line\">Signs:</div><div class=\"answer-line\">Temperature</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Option</th><th>Advantage</th><th>Disadvantage</th></tr></thead><tbody><tr><td>Side effects of antibiotics (including allergy)</td><td>Drug interactions eg with warfarin</td><td>Increasing antimicrobial resistance</td></tr><tr><td>Clostridium difficile diarrhoea</td><td>Alteration of urinary microbiome resulting in promotion of UTI</td><td>Cost</td></tr><tr><td>Nth Syd SAQ paper 2021.2</td><td>https://www.aci.health.nsw.gov.au/__data/assets/pdf_file/0006/273336/vqc-guide-to-using-</td><td>data.pdf</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":20,"title":"","stemText":"41-year-old obese male presents overnight with three days severe right posterior neck pain. He denies having any recent trauma. Pain is ongoing despite paracetamol and oxycodone. He has been triaged to your low acuity area and has been clinically assessed by an ED RMO.","parts":[{"id":"a","label":"Part A","prompt":"What differential diagnoses need to be considered? (4 marks)"},{"id":"b","label":"Part B","prompt":"List important historical findings/features for this patient’s neck pain? (4 Marks) Consultant review finds very limited neck range of movement due to pain and difficulty swallowing due to pain. A lateral neck X-ray is performed."},{"id":"c","label":"Part C","prompt":"Interpret the patient’s lateral neck X-ray? (1 mark)"},{"id":"d","label":"Part D","prompt":"List 2 other important initial investigations? (2 marks)"},{"id":"e","label":"Part E","prompt":"What is the most concerning diagnosis? (1 mark)"},{"id":"f","label":"Part F","prompt":"What is the treatment? (2 marks)"},{"id":"g","label":"Part G","prompt":"What complications may develop? (2 marks)"}],"propPages":["asset:img5671a687dd91234aa8"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">- Deep infection</div><div class=\"answer-line\">Discitis</div><div class=\"answer-line\">Retropharyngeal abscess</div><div class=\"answer-line\">-Cervical artery dissection: vertebral or carotid</div><div class=\"answer-line\">-Subarachnoid haemorrage</div><div class=\"answer-line\">-Muscular: trapezius origin</div><div class=\"answer-line\">-Nerve: occipital neuralgia/nerve impingement</div><div class=\"answer-line\">-Phalangeal infection: quinsy</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">History “red flags”</div><div class=\"answer-line\">Presenting features:</div><div class=\"answer-line\">-Any trauma including minor eg chiropractic manipulation</div><div class=\"answer-line\">-Associated features</div><div class=\"answer-line\">Headache</div><div class=\"answer-line\">Neurological deficit</div><div class=\"answer-line\">Fevers</div><div class=\"answer-line\">Difficulty/painful swallowing</div><div class=\"answer-line\">-Recent LP; post procedure headaches</div><div class=\"answer-line\">PMH:</div><div class=\"answer-line\">Immunosuppressed: medication or disease related</div><div class=\"answer-line\">IV drug user</div><div class=\"answer-line\">Previous malignancy</div><div class=\"answer-line\">Nth Syd SAQ paper 2021.2</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">-marked soft tissue swelling anterior to vertebral bodies C1-4</div><div class=\"answer-line\">Nth Syd SAQ paper 2021.2</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">-Bloods: inflammatory markers; CRP, WCC</div><div class=\"answer-line\">-Blood culture</div><div class=\"answer-line\">-CT neck</div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\">Retropharyngeal abscess.</div></section><section class=\"answer-part\"><h5>Part F</h5><div class=\"answer-line\">-IV antibiotics to cover strep and ANA: IV Augmentin, or cephazolin with metronidazole or</div><div class=\"answer-line\">clinamycin</div><div class=\"answer-line\">-surgical drainage</div></section><section class=\"answer-part\"><h5>Part G</h5><div class=\"answer-line\">-airway compromise</div><div class=\"answer-line\">-extension to mediastinitis</div><div class=\"answer-line\">-sepsis</div><div class=\"answer-line\">-IJV thrombosis (Lemierre’s syndrome)</div><div class=\"answer-line\">Nth Syd SAQ paper 2021.2</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":21,"title":"","stemText":"A 19-year-old primigravida presents to your ED with central abdominal pain. She is 30 weeks pregnant and has no past medical history. Her initial vital signs are:\n\nGCS 15 bp 170/110 hG hr 110/min, RR 24,SpO2 99% RA, Temp 37","parts":[{"id":"a","label":"Part A","prompt":"List 5 differential diagnosis you should consider for the abdominal pain (5 marks)"},{"id":"b","label":"Part B","prompt":"What are the diagnostic criteria for pre-eclampsia? (3 marks)"},{"id":"c","label":"Part C","prompt":"You diagnose preeclampsia. Outline the management steps for this patient (5 marks)"},{"id":"d","label":"Part D","prompt":"These are her pathology results. Interpret these results (2 marks)\n\nHb 84\nPlt 88 x 109/l\nWBC 12.7 x 109/l\nBili 44umol/l\nALT 300u/l\nAST 270u/l\nGGT 42u/l\nALP 96u/l\nLDH 518u/l"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Minimum PET plus 1 other pregnancy related</div><div class=\"answer-line\">Pregnancy related</div><div class=\"answer-line\">PET</div><div class=\"answer-line\">HELLP syndrome</div><div class=\"answer-line\">Placental abruption</div><div class=\"answer-line\">Preterm labour</div><div class=\"answer-line\">Non pregnancy Related</div><div class=\"answer-line\">GIT (Biliary Choloelithisasis/Cholecystitis)</div><div class=\"answer-line\">Hepatic Hepatitis/congestion</div><div class=\"answer-line\">Pancreatitis</div><div class=\"answer-line\">Gastritis</div><div class=\"answer-line\">Appendicitis</div><div class=\"answer-line\">GU (UTI/Pyelonephritis/Renal colic/</div><div class=\"answer-line\">Pneumonia</div><div class=\"answer-line\">DKA</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">HT (BP 140/90 or higher or change of baseline SBP 30 or DBP 15)</div><div class=\"answer-line\">Nth Syd SAQ paper 2021.2</div><div class=\"answer-line\">Proteinuria &gt; 0.1g on at least 2 samples</div><div class=\"answer-line\">+/- oedema dipstick 1+</div><div class=\"answer-line\"> 20 weeks gestation</div><div class=\"answer-line\">Severe pre eclampsia  BP &gt; 160/110 severe proteinuria endorgan effects</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">1. Urgent obstetric consult</div><div class=\"answer-line\">2. Analgesia ( paracetamol/morphine)and anti emetic (metochlopramide or ondansetron IV or</div><div class=\"answer-line\">po)</div><div class=\"answer-line\">3. Left lateral position to optimise blood flow to fetus</div><div class=\"answer-line\">4. Specific treatment for PET Magnesium sulphate Loading dose 4g over 5<strong> </strong>mins and infusion</div><div class=\"answer-line\">2g/hr</div><div class=\"answer-line\">5. Management of fetus CTG Anti D if mother rhesus neg and consider steroids betamethasone</div><div class=\"answer-line\">for impending delivery</div><div class=\"answer-line\">6. Management of BP: Safe controlled reduction of bp/risk of rapid reduction (uterine</div><div class=\"answer-line\">hypoperfusion) vs risk ICH with HT (Hydralazine 5-10mg IV every 15 mins max 40mg then</div><div class=\"answer-line\">infusion 5mg/hr. labetolol 10-20mg IV doubling every 10-20 mins  max 300mg  or infusion 1-</div><div class=\"answer-line\">2mg/min Oral nifedipine GTN infusion advantage in APO)</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Hb 84</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":22,"title":"","stemText":"A 10-day old male infant is brought in because of persistent crying, poor feeding and this rash around his right eye","parts":[{"id":"a","label":"Part A","prompt":"List 4 reasons why he may have persistent crying and poor feeding (4 marks)"},{"id":"b","label":"Part B","prompt":"List the main ways that herpes simplex virus (HSV) is transmitted to the neonate (3 marks)"},{"id":"c","label":"Part C","prompt":"List the 3 main ways that HSV infection presents in the neonatal period with a description\n• f at least one distinguishing feature for each of them (6 marks)"},{"id":"d","label":"Part D","prompt":"It is possible for a neonate with a serious HSV infection to have no skin lesions. List 2 finding on history that are risk factors for HSV infection. (3 Marks)"}],"propPages":["asset:img9a45fc01b00e2f2259"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><em>Herpes meningoencephalitis causing headache poor appetite</em></div><div class=\"answer-line\"><em>Herpetic oropharyngeal mouth ulcers</em></div><div class=\"answer-line\"><em>Keratoconjuntivitis – painful eye</em></div><div class=\"answer-line\"><em>Pneumonitis – sob poor feeding</em></div><div class=\"answer-line\"><em>Painful skin lesions</em></div><div class=\"answer-line\"><em>Disseminated herpes causing other organ failure eg hepatitis</em></div><div class=\"answer-line\"><em>Electrolyte abnormalities</em></div><div class=\"answer-line\"><strong>ii.</strong><strong> </strong></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><em>Intrauterine via placenta (rare)</em></div><div class=\"answer-line\"><em>Perinatal via the genital tract</em></div><div class=\"answer-line\"><em>Postnatal from someone shedding the virus</em></div><div class=\"answer-line\">Nth Syd SAQ paper 2021.2</div><div class=\"answer-line\"><strong>iii.</strong><strong> </strong></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td><em>Skin eye muscle lesions</em></td><td><em>Classic herpetic lesions on skin</em></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\"><em>History- Maternal genital herpes especially active at time of birth, vaginal delivery, prolonged rupture </em></div><div class=\"answer-line\"><em>of membranes, use of a scalp ph monitor, maternal fever, postnatal contact with someone with a </em></div><div class=\"answer-line\"><em>cold sore</em></div><div class=\"answer-line\">Nth Syd SAQ paper 2021.2</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":23,"title":"","stemText":"A 23 year old autistic lady is brought in to your tertiary ED by her carer with PV bleeding following a medical termination two day prior. Her carer is concerned about the amount of pain she is in and he reports she is looking ‘very pale’ Her obs are as follows Afebrile\n\nHR 110bpm\n\nBP 110/80\n\nSats 98% RA\n\nRR 22bpm","parts":[{"id":"a","label":"Part A","prompt":"What important features do you need to ascertain during your assessment of this lady? (5 marks) Following your assessment, the nurse alerts you that the patient is now unresponsive, pale. BP unrecordable and pulse thready, rate about 40-50bpm"},{"id":"b","label":"Part B","prompt":"What is your immediate management now? (4 marks) The patient is stabilised with your above management. Upon reviewing her notes it becomes apparent this is her 3rd medical termination and she has had x1 pregnancy with delivery of a baby boy."},{"id":"c","label":"Part C","prompt":"What other safety features need to be implemented in the care of this patient?"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">When the bleeding started</div><div class=\"answer-line\">How much bleeding – how many pads soaked through</div><div class=\"answer-line\">Any large clots present</div><div class=\"answer-line\">Features of severe acute blood loss – dizziness, light headedness, syncope, shortness of breath</div><div class=\"answer-line\">Features of infection – fever, nausea and vomiting, pain increase</div><div class=\"answer-line\">PMHx</div><div class=\"answer-line\">Past obstetric history – LMP, how pregnant was she, USS done to confirm intra uterine, previous</div><div class=\"answer-line\">miscarriages, pregnancies, where the medical termination took place, who assisted her with process</div><div class=\"answer-line\">(has it been done correctly – mifepristone followed by misoprostol 24-48 hours after) ?rhesus status</div><div class=\"answer-line\">– was anti-d given if &gt;8/40 and negative</div><div class=\"answer-line\">Drug history – esp anticoagulants</div><div class=\"answer-line\">Allergies</div><div class=\"answer-line\">Social history – who the carer is, who looks after her, features of ability to consent to sexual</div><div class=\"answer-line\">intercourse ?concerns about rape</div><div class=\"answer-line\">Nth Syd SAQ paper 2021.2</div><div class=\"answer-line\">Exam – level of pain, assess bleeding, speculum for clots</div><div class=\"answer-line\">General exam to exclude other causes of sepsis</div><div class=\"answer-line\">Investigation – VBG, FBC, G&amp;H, EUC, bHCG, coag studies (?DIC), ?ROTEM</div><div class=\"answer-line\">USS if stable</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Concern about clot retention in cervical os</div><div class=\"answer-line\">Ensure x2 ivc are patent – can bolus 500mls N/Saline, rpt VBG to check Hb</div><div class=\"answer-line\">Repeat speculum exam and remove clot if present – patient likely to respond well, once removed</div><div class=\"answer-line\">If no clot or not response with this, start blood transfusion bolus and then through warmer – aim for</div><div class=\"answer-line\">MAP 60, clinical improvement in patient and GCS</div><div class=\"answer-line\">Ensure O&amp;G aware of patient ?retained products, may require OT / D&amp;C</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Question of social situation – boyfriend, consent to have sex, contraception, at risk of STIs</div><div class=\"answer-line\">Explain concerns &amp; offer assistance</div><div class=\"answer-line\">Offer form of contraception</div><div class=\"answer-line\">Assess competence, SW if severely autistic / NOK</div><div class=\"answer-line\">Enlist other assistance/sources of info e.g. LMO</div><div class=\"answer-line\">Nth Syd SAQ paper 2021.2</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":24,"title":"","stemText":"A 10 year old girl is BIBA to your rural ED. She has been unwell for the past couple of days with vomiting. Today she was more lethargic than normal and mum was worried this evening when she was very slow to rouse from an afternoon nap. She is usually well, with no background history of note She is drowsy on exam but opens her eyes to painful stimuli She is afebrile\n\nHR 160bpm\n\nBP 80/60\nCap refil 4seconds\n\nSats 99% RA, RR 40bpm\nHer VBG is as below\n\npH 7.06\n\npCO2 23\n\npO2 47\n\nHCO3 6\n\nBE -22.4\n\nNa 137\n\nK 4.8\n\nCl 105\nGluc 23\n\nLac 3.6","parts":[{"id":"a","label":"Part A","prompt":"Describe and interpret the gas above (6 marks)"},{"id":"b","label":"Part B","prompt":"Detail your ongoing management of this 10 year old girl (8 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Severe metabolic acidosis</div><div class=\"answer-line\">AG = 137 – (105 + 6) = 26 -&gt; <strong>HAGMA</strong></div><div class=\"answer-line\">Nth Syd SAQ paper 2021.2</div><div class=\"answer-line\">Delta ratio = 26 – 12 / 24 – 6 = 14 / 18 -&gt; 0.8 – roughly pure HAGMA but could be mixed HAGMA and</div><div class=\"answer-line\">NAGMA (due to vomiting)</div><div class=\"answer-line\">Resp compensation = 1.5 (6) +8 = 17 -&gt; <strong>resp alkalosis</strong> – concern as patient quite drowsy, therefore</div><div class=\"answer-line\">may not be able to compensate. This needs to be monitored</div><div class=\"answer-line\"><strong>Na = 137 – corrected = 23-10/3 = 141 </strong></div><div class=\"answer-line\"><strong>K 4.8 – corrected = 3.3</strong> – needs to monitored closely with correction of pH</div><div class=\"answer-line\"><strong>Lac 3.6</strong> – likely secondary to dehydration / tissue ischaemia</div><div class=\"answer-line\"><strong>Imp </strong>DKA (need blood / urine ketones) with vomiting, clinically drowsy and needs urgent</div><div class=\"answer-line\">resuscitation</div><div class=\"answer-line\"><strong>ii.</strong><strong> </strong></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">As per rch guidelines</td></tr><tr><td>-</td><td>Note <strong>rural ED – need to contact NETS</strong> early as will need to be managed by paediatric team</td></tr><tr><td colspan=\"2\">comfortable with new diagnosis diabetes and DKA</td></tr><tr><td>-</td><td>Need x2 ivc and <strong>urgent fluid bolus</strong> 10mls/kg N/Saline. Repeat x2, aim for cap refil &lt;3</td></tr><tr><td colspan=\"2\">seconds, improvement of GCS, BP and HR</td></tr><tr><td>-</td><td><strong>Start rehydration fluids</strong> N/Saline <strong>plus 40mmol/KCl as K&lt;5.5</strong> (not if patient anuric) –</td></tr><tr><td colspan=\"2\">maintenance plus %dehydration (likely about 5-7%)</td></tr><tr><td>-</td><td>Nurse head up</td></tr><tr><td>-</td><td>Oxygen can be given due to circulatory impairment and shock</td></tr><tr><td>-</td><td><strong>Cardiac monitoring </strong></td></tr><tr><td>-</td><td>Consider urinary catheter for fluid monitoring</td></tr><tr><td>-</td><td>After 1 hour commence <strong>insulin 0.1units/kg/hour</strong></td></tr><tr><td>-</td><td><strong>30 minutely VBGs to check electrolytes and glucose</strong> level – if BGL &lt;15 change fluids to</td></tr><tr><td colspan=\"2\">contact 5%dextrose (and potassium), if glucose level falling rapidly (&gt;5mmol/L/hour) or</td></tr><tr><td colspan=\"2\">&lt;5mmol/L  and child still acidotic, increase glucose content to 10%</td></tr><tr><td>-</td><td>Monitor airway – unlikely to need intubation. Unless continues to be drowsy (increase CO2)</td></tr><tr><td colspan=\"2\">/ vomiting / need for transfer and protect airway</td></tr><tr><td>-</td><td><strong>Liaise with local paeds / regional paediatric /tertiary hospital </strong></td></tr><tr><td colspan=\"2\">Nth Syd SAQ paper 2021.2</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":25,"title":"","stemText":"A 55 year-old man present with sudden, severe chest pain","parts":[{"id":"a","label":"Part A","prompt":"List 3 pre-existing conditions that confer a high risk of aortic dissection (3 marks)"},{"id":"b","label":"Part B","prompt":"List 3 examination findings that confer a high risk of aortic dissection (3 marks)"},{"id":"c","label":"Part C","prompt":"List 3 chest x-ray findings described in aortic dissection (3 marks)"},{"id":"d","label":"Part D","prompt":"Discuss the role of D-dimer in the evaluation of aortic dissection (3 marks)"},{"id":"e","label":"Part E","prompt":"Name 2 drugs from 2 different classes which can be used to reduce shear force stress on\nan intimal flap. For each, write brief notes outlining the drug’s role (4 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Marfan syndrome, family history of aortic disease, known aortic valve disease, known thoracic aortic</div><div class=\"answer-line\">aneurysm, or previous aortic manipulation, including cardiac surgery.</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Perfusion deficit, including pulse deficit, systolic blood pressure difference, or focal neurologic</div><div class=\"answer-line\">deficit, or with aortic diastolic murmur and hypotension/shock</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Widened mediastinum</td></tr><tr><td>•</td><td>Pleural effusion</td></tr><tr><td>•</td><td>Irregular/wide aortic contour</td></tr><tr><td>•</td><td>Double aortic contour/displaced calcification</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">ADvISED Trial Nazerian et al 2018 is the only prospective evaluation of combining clinical risk</div><div class=\"answer-line\">stratification (e.g. the ADD-RS) with D-dimer. Multi-centre 1850 patients. Sensitivity 98.8%. 8</div><div class=\"answer-line\">patients with negative D-dimer had AAS.</div><div class=\"answer-line\">Issues: observational study, half of cohort had no definitive imaging, short length of follow-up &amp;</div><div class=\"answer-line\">high prevalence of AD in the population studied. Most authors suggest this holds promise but</div><div class=\"answer-line\">needs external validation for reproducibility.</div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Esmolol (beta blocker)</td><td>Rapid onset, titratable, short duration of action – can be switched of if hypotension,</td></tr><tr><td>bronchospasm etc occur. Clearance not affected by renal/hepatic dysfunction</td><td>Relatively unfamiliar to staff, need continuous infusion, continuous monitoring</td></tr><tr><td>Metoprolol (beta blocker)</td><td>IV available, familiar to staff</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":26,"title":"","stemText":"A 42-year-old man has developed a febrile illness one week after returning from a business trip to Papua New Guinea.","parts":[{"id":"a","label":"Part A","prompt":"What questions specific to this case should form part of the history that you will obtain? (6 marks)"},{"id":"b","label":"Part B","prompt":"Describe how the diagnosis of malaria can be established (3 marks)"},{"id":"c","label":"Part C","prompt":"Plasmodium falciparum has several characteristics that are markedly different to the other Plasmodia species. Briefly describe 3 differences (3 marks)"},{"id":"d","label":"Part D","prompt":"List 4 complications that occur in severe P falciparum infection (4 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Travel history – where exactly, urban/rural, resort/airconditioning etc, duration, prophylaxis</div><div class=\"answer-line\">(malaria/other), mosquito protection/bites, other exposures, sexual activities</div><div class=\"answer-line\">History of current illness – symptom onset, cyclical fevers, rash.  System review - a/n/v/d, blood in</div><div class=\"answer-line\">stool, abdo pain – URTI/LRTI/ENT symptoms etc.  Any self-administered Rx</div><div class=\"answer-line\">[ General history – normal health, PHx, meds, allergies …altogether only constitute one point.</div><div class=\"answer-line\">Important but excluded by the question “…specific to this case…”]</div><div class=\"answer-line\"><strong>ii.</strong><strong> </strong></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Films – thin (for speciation), thick (if no parasites seen on thin film). One negative does not</div><div class=\"answer-line\">exclude Dx – protocols vary but typically repeat 3-4 times over 24h</div><div class=\"answer-line\">•</div><div class=\"answer-line\">Antigen tests – esp for PF</div><div class=\"answer-line\"><strong>iii.</strong><strong> </strong></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">PF does not have a hypnozoite phase leading to relapses as occurs with vivax/ovale/malariae</td></tr><tr><td>•</td><td>PF causes high percentage parasitaemia (the other only a low %)</td></tr><tr><td>•</td><td>Many areas have PF with chloroquine resistance – the other species are all chloroquine</td></tr><tr><td colspan=\"2\">responsive</td></tr><tr><td>•</td><td>Major complications (e.g. cerebral malaria, ARF etc) and mortality are significant in PF – the</td></tr><tr><td colspan=\"2\">other species generally cause less severe disease</td></tr><tr><td colspan=\"2\"><strong>iv.</strong><strong> </strong></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Nth Syd SAQ paper 2021.2</td></tr><tr><td>•</td><td>Cerebral malaria</td></tr><tr><td>•</td><td>Respiratory failure (ARDS-type)</td></tr><tr><td>•</td><td>Acute Tubular Necrosis/ARF</td></tr><tr><td>•</td><td>Hypoglycaemia</td></tr><tr><td>•</td><td>Haemolysis/anaemia</td></tr><tr><td>•</td><td>Splenomegaly/rupture</td></tr><tr><td>•</td><td>Lactic acidosis</td></tr><tr><td colspan=\"2\">Nth Syd SAQ paper 2021.2</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":27,"title":"","stemText":"A 16-year-old boy presents with his parents after coughing up blood a week after tonsillectomy. His bleeding has ceased now and his observations are all in the normal range.","parts":[{"id":"a","label":"Part A","prompt":"What are the key components of your initial assessment? (6 marks) He is taken into the resuscitation room, IV access established, monitoring attached and ENT are en route The ENT trolley and the difficult airway trolley are immediately available. Suddenly the boy begins coughing up large volumes of blood and has developed stridor."},{"id":"b","label":"Part B","prompt":"Outline your management. (7 marks) ENT and anaesthetics are not yet present when the patient becomes cyanotic and is unable to breathe."},{"id":"c","label":"Part C","prompt":"How will you manage him now? (2 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Define amount/timing of blood loss: ooze vs clot, duration (note bleeding can be</div><div class=\"answer-line\">occult - swallow blood)</div><div class=\"answer-line\">Background of bleeding disorder</div><div class=\"answer-line\">Other co existent illness</div><div class=\"answer-line\">Symptoms of significant blood loss</div><div class=\"answer-line\">Airway, breathing: signs of aspiration or compromise  = hypoxia, tachypnea, focal lung</div><div class=\"answer-line\">findings</div><div class=\"answer-line\">Circulation: Signs of shock: pallor, tachycardia, note hypotension is a late sign</div><div class=\"answer-line\">ENT: active bleeding from tonsillar beds</div><div class=\"answer-line\">Other: Fever, evidence of infection</div><div class=\"answer-line\">G&amp;H, FBC, coags?, VBG for rapid Hb</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Call anaesthetist to help prepare for imminent  intubation in OT</div><div class=\"answer-line\">Nth Syd SAQ paper 2021.2</div><div class=\"answer-line\">All team full PPE</div><div class=\"answer-line\">Sit patient forward, keep calm, NBM</div><div class=\"answer-line\">Suction +/- double suction</div><div class=\"answer-line\">Prep difficult airway trolley</div><div class=\"answer-line\">Magill’s with gauze (ideally soaked in Ad / TXA)</div><div class=\"answer-line\">Lateral pressure tonsillar bed under direct vision</div><div class=\"answer-line\">Alternative = nebulised</div><div class=\"answer-line\">Blood transfusion +/- Massive Transfusion Protocol activate if...</div><div class=\"answer-line\">Give TXA =  15mg/kg , up to 1g IV</div><div class=\"answer-line\">(IV ABs - ideal but not urgent, benpen high dose)</div><div class=\"answer-line\">Parental and patient explanation</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Urgent/ immediate airway control/securing</div><div class=\"answer-line\">Simple airway manoeuvers, BVM with high flow O2</div><div class=\"answer-line\">RSI with ++suction</div><div class=\"answer-line\">State drugs used</div><div class=\"answer-line\">Note VL/CMAC could be difficult due to blood</div><div class=\"answer-line\">Cricothyroidotomy if unable</div><div class=\"answer-line\">As above- MTP etc</div><div class=\"answer-line\">Nth Syd SAQ paper 2021.2</div><div class=\"answer-line\">Nth Syd SAQ paper 2021.2</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false}]);
